export interface SchemaMutationScenario {
  readonly id: string;
  readonly path: string;
  readonly value: unknown;
  readonly expectValid: boolean;
  readonly note: string;
}

export interface RoundtripScenario {
  readonly id: string;
  readonly normalizeWhitespace: boolean;
  readonly includeTrailingNewline: boolean;
  readonly cloneMode: number;
  readonly hashJoinSalt: string;
}

export interface HashScenario {
  readonly id: string;
  readonly left: unknown;
  readonly right: unknown;
  readonly join: readonly string[];
}

